import {OFFICIAL_MAINTENANCE_JA as catalog}from './official-maintenance-ja.js?v=20261111-94';
export const HOTEND_SELECTOR_COPY={"title":["ホットエンド一式の交換方法を選ぶ","Choose the hotend assembly procedure","Vybrat postup výměny hotendu","Anleitung für den Hotend-Tausch wählen"],"entry":["機種・交換方法を確認する","Check model and replacement method","Ověřit model a způsob výměny","Modell und Austauschverfahren prüfen"],"model":["プリンターの機種","Printer model","Model tiskárny","Druckermodell"],"intro":["プリンターの機種を選びます。CORE One / CORE One+は、このサイトで交換手順を確認できます。","Select your printer model. Follow the CORE One / CORE One+ procedure here.","Vyberte model tiskárny. Postup pro CORE One / CORE One+ můžete projít přímo zde.","Druckermodell auswählen. Die Anleitung für CORE One / CORE One+ lässt sich direkt hier öffnen."],"compatibility":["公式記事はPrusa NozzleとPrusa Nozzle CHTの各径を対象にしています。","The official selector covers the diameters of both Prusa Nozzle and Prusa Nozzle CHT.","Oficiální rozcestník zahrnuje průměry Prusa Nozzle i Prusa Nozzle CHT.","Der offizielle Wegweiser gilt für die Durchmesser von Prusa Nozzle und Prusa Nozzle CHT."],"warning":["機種が異なる手順は使いません。ノズル単体交換・V6アダプター・HT構成は、下の該当する公式ガイドで方法を確認します。","Use the procedure for your model. For nozzle-only replacement, a V6 adapter or an HT configuration, check the corresponding official guide below.","Použijte postup pro svůj model. Pro samostatnou trysku, adaptér V6 nebo sestavu HT ověřte metodu v příslušném oficiálním návodu níže.","Die Anleitung für das eigene Modell verwenden. Für den reinen Düsenwechsel, V6-Adapter oder eine HT-Konfiguration die passende offizielle Anleitung unten prüfen."],"start":["CORE One / CORE One+の交換手順を開く","Open the CORE One / CORE One+ procedure","Otevřít postup pro CORE One / CORE One+","Anleitung für CORE One / CORE One+ öffnen"],"external":["この機種の公式手順を開く","Open the official procedure for this model","Otevřít oficiální postup pro tento model","Offizielle Anleitung für dieses Modell öffnen"],"foreign":["選んだ機種の公式手順を開いてください。","Open the official procedure for the selected model.","Otevřete oficiální postup pro vybraný model.","Die offizielle Anleitung für das gewählte Modell öffnen."],"selectorSource":["機種別の公式記事","Official model selector","Oficiální rozcestník modelů","Offizieller Modellwegweiser"],"procedureSource":["対応する公式説明と写真","Matching official instructions and photos","Odpovídající oficiální popis a fotografie","Passende offizielle Anleitung und Fotos"],"otherMethods":["別の交換方法・構成の公式ガイド","Official guides for other methods and configurations","Oficiální návody pro jiné metody a sestavy","Offizielle Anleitungen für andere Verfahren und Konfigurationen"]};
export const HOTEND_SELECTOR_SOURCE="https://help.prusa3d.com/article/changing-or-replacing-the-nextruder-hotend_768975";
export const HOTEND_MODELS=[{"id":"core-one","label":["CORE One / CORE One+","CORE One / CORE One+","CORE One / CORE One+","CORE One / CORE One+"],"task":"hotend","source":"https://help.prusa3d.com/guide/how-to-replace-a-hotend-assembly-core-one_385707"},{"id":"core-one-l","label":["CORE One L / CORE One L+","CORE One L / CORE One L+","CORE One L / CORE One L+","CORE One L / CORE One L+"],"source":"https://help.prusa3d.com/guide/how-to-replace-a-hotend-assembly-core-one-l_934741"},{"id":"signature-oak","label":["Signature Oak","Signature Oak","Signature Oak","Signature Oak"],"source":"https://help.prusa3d.com/guide/how-to-replace-a-hotend-assembly-core-one_385707"},{"id":"mk4s","label":["MK4S / MK3.9S","MK4S / MK3.9S","MK4S / MK3.9S","MK4S / MK3.9S"],"source":"https://help.prusa3d.com/guide/how-to-replace-a-hotend-assembly-mk4s-mk3-9s_765342"},{"id":"mk4","label":["MK4 / MK3.9","MK4 / MK3.9","MK4 / MK3.9","MK4 / MK3.9"],"source":"https://help.prusa3d.com/guide/how-to-replace-a-hotend-assembly-mk4-mk3-9_645439"},{"id":"xl-single","label":["XL（シングルツール）","XL single-tool","XL s jednou nástrojovou hlavou","XL mit einem Werkzeugkopf"],"source":"https://help.prusa3d.com/guide/how-to-replace-the-hotend-assembly-xl-single-tool_409911"},{"id":"xl-multi","label":["XL（マルチツール）","XL multi-tool","XL s více nástrojovými hlavami","XL mit mehreren Werkzeugköpfen"],"source":"https://help.prusa3d.com/guide/how-to-replace-the-hotend-assembly-xl-multi-tool_573711"}];
export const HOTEND_ALTERNATIVES=[{"label":["ノズル単体の交換方法","Nozzle-only replacement","Výměna samotné trysky","Reiner Düsenwechsel"],"source":"https://help.prusa3d.com/article/changing-or-replacing-the-prusa-nozzle_734706"},{"label":["V6ノズルアダプター","V6 nozzle adapter","Adaptér trysky V6","V6-Düsenadapter"],"source":"https://help.prusa3d.com/article/installing-or-changing-the-nextruder-v6-nozzle-adapter_823792"},{"label":["HT Hotendの構成","HT Hotend configuration","Sestava HT Hotend","HT-Hotend-Konfiguration"],"source":"https://help.prusa3d.com/guide/how-to-install-ht-hotend-upgrade-core-one-core-one-l_1080575"}];
import {LIBRARY_COPY,guideText,groupText,libraryCount,equipmentText} from './maintenance-library-locales.js?v=20261113-125';
export {LIBRARY_COPY} from './maintenance-library-locales.js?v=20261113-125';
import {ALERT_COPY} from './maintenance-alert-data.js?v=20261113-127';
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const normalize=(s,language='ja')=>{const normalized=String(s).normalize('NFKC').toLocaleLowerCase(language);return language==='ja'?normalized:normalized.normalize('NFD').replace(/\p{M}/gu,'');};
export function findOfficialGuides({query='',group='all',extras=false,language='ja'}={}){
 const locale=['ja','en','cs','de'].includes(language)?language:'ja',words=normalize(query,locale).trim().split(/\s+/).filter(Boolean);
 return catalog.guides.filter(g=>{const translated=guideText(g,locale),original=`${g.title} ${g.search} ${g.equipment||''}`,haystack=locale==='ja'?original:`${original} ${translated.title} ${translated.note||''} ${translated.equipment||''}`;return(extras||!g.equipment)&&(group==='all'||g.group===group)&&words.every(word=>normalize(haystack,locale).includes(word));});
}
export function createMaintenanceLibrary({dialog,body,title,language,tasks,onTask,onAlert=()=>{}}){
 let query='',group='all',extras=false,hotendSelector=false,hotendModel='core-one';
 const text=a=>a[({ja:0,en:1,cs:2,de:3})[language()]??0];
 function results(){
  const items=findOfficialGuides({query,group,extras,language:language()});
  body.querySelector('[data-library-count]').textContent=libraryCount(items.length,language());
  body.querySelector('[data-library-results]').innerHTML=items.length?items.map(g=>`<article class="library-card" data-guide-id="${g.id}"><p class="library-part">${esc(groupText(catalog.groups.find(x=>x.id===g.group),language()))}${g.equipment?`<span class="library-equipment">${esc(equipmentText(guideText(g,language()).equipment,language()))}</span>`:''}</p><h3>${esc(guideText(g,language()).title)}</h3>${g.note?`<p class="library-note">${esc(guideText(g,language()).note)}</p>`:''}<div class="library-links"><a href="${esc(g.url)}" target="_blank" rel="noopener">${esc(text(LIBRARY_COPY.official))}</a>${g.selector==='maintenance-alerts'?`<button type="button" data-library-alert="${g.id}">${esc(text(ALERT_COPY.entry))} →</button>`:g.selector==='nextruder-hotend'?`<button data-library-hotend-selector>${esc(text(HOTEND_SELECTOR_COPY.entry))} →</button>`:(g.tasks||[]).map(id=>`<button data-library-task="${id}">${esc(g.tasks.length===1?text(LIBRARY_COPY.local):text(tasks.find(t=>t.id===id).title))} →</button>`).join('')}</div></article>`).join(''):`<p class="library-empty">${esc(text(LIBRARY_COPY.empty))}</p>${!extras?`<button data-library-extras>${esc(text(LIBRARY_COPY.searchExtras))}</button>`:''}`;
 }
 function hotendSelection(){
  const model=HOTEND_MODELS.find(m=>m.id===hotendModel);
  const local=model.task==='hotend'&&catalog.guides.find(g=>g.id==='768975').tasks?.includes('hotend');
  body.querySelector('[data-hotend-selection]').innerHTML=`<article class="library-card"><h3>${esc(text(model.label))}</h3>${local?'':`<p class="library-note">${esc(text(HOTEND_SELECTOR_COPY.foreign))}</p>`}<div class="library-links">${local?`<button data-hotend-start>${esc(text(HOTEND_SELECTOR_COPY.start))} →</button>`:''}<a data-hotend-official href="${esc(model.source)}" target="_blank" rel="noopener">${esc(text(HOTEND_SELECTOR_COPY[local?'procedureSource':'external']))} ↗</a></div></article>`;
 }
 function renderHotendSelector(){
  title.textContent=text(HOTEND_SELECTOR_COPY.title);
  dialog.setAttribute('aria-labelledby',title.id);
  body.innerHTML=`<div class="maintenance-library" data-hotend-selector-panel><p class="library-intro">${esc(text(HOTEND_SELECTOR_COPY.intro))}</p><label class="library-group">${esc(text(HOTEND_SELECTOR_COPY.model))}<select data-hotend-model>${HOTEND_MODELS.map(m=>`<option value="${m.id}"${m.id===hotendModel?' selected':''}>${esc(text(m.label))}</option>`).join('')}</select></label><p class="library-note" data-hotend-compatibility>${esc(text(HOTEND_SELECTOR_COPY.compatibility))}</p><p class="library-note" data-hotend-warning>${esc(text(HOTEND_SELECTOR_COPY.warning))}</p><div data-hotend-selection></div><nav class="library-links"><a data-hotend-source href="${HOTEND_SELECTOR_SOURCE}" target="_blank" rel="noopener">${esc(text(HOTEND_SELECTOR_COPY.selectorSource))} ↗</a></nav><details><summary>${esc(text(HOTEND_SELECTOR_COPY.otherMethods))}</summary><nav class="library-links">${HOTEND_ALTERNATIVES.map(m=>`<a href="${esc(m.source)}" target="_blank" rel="noopener">${esc(text(m.label))} ↗</a>`).join('')}</nav></details></div>`;
  hotendSelection();
 }
 function openHotendSelector(){hotendSelector=true;dialog.dataset.mode='library';render();if(!dialog.open)dialog.showModal();body.scrollTop=0;body.querySelector('[data-hotend-model]').focus({preventScroll:true});}
 function render(){
  if(dialog.dataset.mode!=='library')return;
  if(hotendSelector){renderHotendSelector();return;}
  title.textContent=text(LIBRARY_COPY.title);
  body.innerHTML=`<div class="maintenance-library"><h2 tabindex="-1">${esc(text(LIBRARY_COPY.heading))}</h2><p class="library-intro">${esc(text(LIBRARY_COPY.intro))}</p><label class="library-search">${esc(text(LIBRARY_COPY.query))}<input type="search" data-library-query value="${esc(query)}" placeholder="${esc(text(LIBRARY_COPY.placeholder))}" enterkeyhint="search" autocomplete="off" autocapitalize="none" spellcheck="false"></label><label class="library-group">${esc(text(LIBRARY_COPY.group))}<select data-library-group><option value="all">${esc(text(LIBRARY_COPY.all))}</option>${catalog.groups.map(g=>`<option value="${g.id}"${g.id===group?' selected':''}>${esc(groupText(g,language()))}</option>`).join('')}</select></label><label class="library-extra"><input type="checkbox" data-library-include-extras${extras?' checked':''}><span>${esc(text(LIBRARY_COPY.extras))}</span></label><p class="library-count" data-library-count role="status" aria-live="polite"></p><div data-library-results></div><p class="library-index">${esc(text(LIBRARY_COPY.checked))}${catalog.checkedAt}<br><a href="${catalog.sources[1]}" target="_blank" rel="noopener">${esc(text(LIBRARY_COPY.index))}</a></p></div>`;
  results();
 }
 body.addEventListener('input',e=>{if(dialog.dataset.mode!=='library')return;if(e.target.hasAttribute('data-library-query')){query=e.target.value;results();}});
 body.addEventListener('change',e=>{
  if(dialog.dataset.mode!=='library')return;
  if(hotendSelector){if(e.target.hasAttribute('data-hotend-model')&&HOTEND_MODELS.some(m=>m.id===e.target.value)){hotendModel=e.target.value;hotendSelection();}return;}
  if(e.target.hasAttribute('data-library-group')){group=e.target.value;if(group==='accessories'){extras=true;body.querySelector('[data-library-include-extras]').checked=true;}results();}
  if(e.target.hasAttribute('data-library-include-extras')){extras=e.target.checked;if(!extras&&group==='accessories'){group='all';body.querySelector('[data-library-group]').value=group;}results();}
 });
 body.addEventListener('click',e=>{
  if(dialog.dataset.mode!=='library')return;
  const b=e.target.closest('button');if(!b)return;
  if(b.hasAttribute('data-library-alert')){onAlert(b.dataset.libraryAlert);return;}
  if(b.hasAttribute('data-library-hotend-selector')){openHotendSelector();return;}
  if(hotendSelector){if(b.hasAttribute('data-hotend-start')&&hotendModel==='core-one'&&catalog.guides.find(g=>g.id==='768975').tasks?.includes('hotend')){dialog.close();onTask('hotend');}return;}
  if(b.hasAttribute('data-library-extras')){extras=true;body.querySelector('[data-library-include-extras]').checked=true;results();}
  const id=b.dataset.libraryTask;
  if(id&&findOfficialGuides({query,group,extras,language:language()}).some(g=>g.tasks?.includes(id))){dialog.close();onTask(id);}
 });
 return {open(){hotendSelector=false;dialog.dataset.mode='library';render();if(!dialog.open)dialog.showModal();body.scrollTop=0;body.querySelector('h2').focus({preventScroll:true});},openHotendSelector,render};
}
